Section Build.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x8 x9 x20 x21 x22 x23 x24 x25 x26 x27 x31 : word).
  Variables (m : amem) (TD WK : Z) (tl M1 : Z) (jt : list byte) (syms : list (option Z)).
  Variable POST : machine_state -> Prop.
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis HM1 : 1 <= M1 <= 256.
  Hypothesis HJT : length jt = (4 * Z.to_nat (2^tl))%nat.
  Hypothesis HSL : length syms = Z.to_nat (2^tl).
  Hypothesis BTD : ablk TD (TD + 4 * 2^tl).
  Hypothesis BWK : ablk WK (WK + 2 * M1).
  Hypothesis DTW : TD + 4 * 2^tl <= WK \/ WK + 2 * M1 <= TD.
  Hypothesis T4 : TD mod 4 = 0.
  Hypothesis W2 : WK mod 2 = 0.
  Hypothesis ZT : zshadow m TD (4 * 2^tl).
  Hypothesis ZW : zshadow m WK (2 * M1).
  Hypothesis RT : rng RNG TD (4 * 2^tl).
  Hypothesis RTS : rng RNG (shad TD) (nshad (4 * 2^tl + TD mod 8)).
  Hypothesis RW : rng RNG WK (2 * M1).
  Hypothesis RWS : rng RNG (shad WK) (nshad (2 * M1 + WK mod 8)).

  Definition blA_W : list (Z * Z) := [(TD, TD + 4 * 2^tl); (WK, WK + 2 * M1)].

  Definition blA_inv (m1 : amem) (u : Z) (snext : list Z) (acc : list dcell) : Prop :=
    u8arr asegs m1 TD (tdb jt syms acc u)
    /\ u8arr asegs m1 WK (u16s (map (Z_to_bv 64) snext))
    /\ munch blA_W m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1.

  Notation STB pc mm u x10 x11 x14 x29 x30 :=
    (MS (mkR x1 sp gp tp (Z_to_bv 64 (TD + 4 * u)) (Z_to_bv 64 2147450880) (Z_to_bv 64 16843009) x8 x9 x10 x11
             (Z_to_bv 64 1431655765) (Z_to_bv 64 tl) x14 (Z_to_bv 64 858993459) (Z_to_bv 64 252645135)
             (Z_to_bv 64 (TD + 3 + 4 * u)) (Z_to_bv 64 (2^tl)) (Z_to_bv 64 WK) x20
             x21 x22 x23 x24 x25 x26 x27 (Z_to_bv 64 (2^tl - u)) x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma bl_loopA : forall f u snext acc r m1 (x10 x11 x14 x29 x30 : word),
    build_loop tl f u syms snext acc = Ok r ->
    Z.of_nat f = 2^tl - u -> 0 <= u < 2^tl -> zlen acc = u -> zlen snext = M1 ->
    Forall (fun v => 0 <= v < 65536) snext ->
    blA_inv m1 u snext acc ->
    (forall m2 snext' (y10 y11 y14 y29 y30 : word), zlen r = 2^tl -> blA_inv m2 (2^tl) snext' r ->
       evtF asegs RNG POST (STB 0x95c38 m2 (2^tl) y10 y11 y14 y29 y30)) ->
    evtF asegs RNG POST (STB 0x95b58 m1 u x10 x11 x14 x29 x30).
Proof.
